using UnityEngine;

/// <summary>
/// Attached to crisp, solid shadow platforms generated by ShadowWallBaker.
/// Identifies the platform as firm, solid ground that prevents characters from sinking.
/// </summary>
[SelectionBase]
[DisallowMultipleComponent]
public class ShadowSolidPlatform : MonoBehaviour
{
    [Header("Shadow Attributes")]
    [Tooltip("Normalized shadow intensity of this solid platform (0 = light, 1 = darkest core).")]
    [Range(0f, 1f)]
    public float shadowIntensity = 1.0f;

    [Tooltip("Unique platform ID generated during bake.")]
    public int platformId;

    [Header("Physics Configuration")]
    [Tooltip("Reference to the solid PolygonCollider2D.")]
    public PolygonCollider2D polygonCollider;

    private void Reset()
    {
        polygonCollider = GetComponent<PolygonCollider2D>();
        if (polygonCollider != null)
        {
            polygonCollider.isTrigger = false;
        }
    }
}
